def _ragged_a2a_kernel_orbit_greedy_16_8_8_pfc(
    input_offsets_ref,
    output_offsets_ref,
    sizes_ref,
    total_send_amount_ref,
    total_recv_amount_ref,
    num_packets_per_group_ref,
    dest_table_ref,  # int32[N, K] in SMEM — pass as extra pallas_call input
    x_ref,
    _,
    o_ref,
    scratch_ref,
    send_sem,
    recv_sem,
    scratch_sems,
    *,
    axis_name,
    transpose,
    packet_size,
    enable_checks: bool = False,
):
    """Orbit-greedy P2P AllToAll kernel for slice=(16, 8, 8).

    Signature: same as `_ragged_a2a_kernel_point_to_point` PLUS one extra
    Ref input `dest_table_ref` (int32[N, K] in SMEM, slot 6). Other
    differences vs reference:
      * Iteration order = OrbitGreedy firing order (vs rotation).
      * Destinations are looked up in `dest_table_ref` (twist-aware).
      * `transpose=True` is NOT supported (would need regen).
      * Assumes 1 group per device (uniform AllToAll).
      * `axis_name` is a flat string (e.g. "x"), as in the reference.
    """
    assert scratch_ref is None
    del scratch_ref
    assert scratch_sems is None
    del scratch_sems
    assert not transpose, (
        "transpose=True not supported by orbit-greedy kernel; use reference."
    )

    my_flat = jax.lax.axis_index(axis_name)
    axis_size_local = jax.lax.axis_size(axis_name)

    num_groups = sizes_ref.shape[0]
    assert num_groups == 1024, (
        f"Expected num_groups=1024 (uniform AllToAll on (16, 8, 8)); got {num_groups}"
    )
    groups_per_shard, r = divmod(num_groups, axis_size_local)
    assert r == 0 and groups_per_shard == 1, (
        "orbit-greedy kernel assumes 1 group per device"
    )

    if axis_size_local > 1:
        ragged_collectives_utils.main_barrier(
            axis_name,
            barrier_type=ragged_collectives_utils.BarrierType.ALL_TO_ALL,
        )

    num_packets = num_packets_per_group_ref[0]

    def _issue_packet(packet_idx, group_idx, dst_device_id):
        size = lax.min(
            packet_size,
            lax.max(sizes_ref[group_idx] - packet_idx * packet_size, 0),
        )
        input_offset = input_offsets_ref[group_idx] + packet_idx * packet_size
        output_offset = output_offsets_ref[group_idx] + packet_idx * packet_size

        if enable_checks:
            pl.debug_check(sizes_ref[group_idx] >= 0, "size<0")
            pl.debug_check(size >= 0, "transfer size<0")
            pl.debug_check(input_offset >= 0, "input_offset<0")
            pl.debug_check(output_offset >= 0, "output_offset<0")
            pl.debug_check(
                input_offset + size <= x_ref.shape[0],
                "input_offset+size > x_ref.shape[0]",
            )
            pl.debug_check(
                output_offset + size <= o_ref.shape[0],
                "output_offset+size > o_ref.shape[0]",
            )

        @pl.when(size > 0)
        def _():
            if axis_size_local > 1:
                pltpu.make_async_remote_copy(
                    x_ref.at[pl.ds(input_offset, size)],
                    o_ref.at[pl.ds(output_offset, size)],
                    device_id=dst_device_id,
                    send_sem=send_sem,
                    recv_sem=recv_sem,
                ).start()
            else:
                pltpu.make_async_copy(
                    x_ref.at[pl.ds(input_offset, size)],
                    o_ref.at[pl.ds(output_offset, size)],
                    sem=send_sem,
                ).start()

    def _self_body(packet_idx, _state):
        _issue_packet(packet_idx, my_flat, {axis_name: my_flat})
        return _state

    jax.lax.fori_loop(0, num_packets, _self_body, None)

    # ---- per-step SEND drain; single RECV drain at the end ----
    _self_bytes = sizes_ref[my_flat]
    pltpu.make_async_copy(
        o_ref.at[pl.ds(0, _self_bytes)],
        o_ref.at[pl.ds(0, _self_bytes)],
        send_sem,
    ).wait()

    def _issue_orbit(k):
        dst_flat = dest_table_ref[my_flat, k]
        dst_dev = {axis_name: dst_flat}
        def _pb(packet_idx, _state):
            _issue_packet(packet_idx, dst_flat, dst_dev)
            return _state
        jax.lax.fori_loop(0, num_packets, _pb, None)

    def _drain_step(step_indices):
        # SEND drain only: wait for this step's own sends.
        cum = 0
        for k in step_indices:
            cum = cum + sizes_ref[dest_table_ref[my_flat, k]]
        pltpu.make_async_copy(
            o_ref.at[pl.ds(0, cum)],
            o_ref.at[pl.ds(0, cum)],
            send_sem,
        ).wait()

    # ---- OrbitGreedy step 0 (6 orbit(s)) ----
    _issue_orbit(0)
    _issue_orbit(1)
    _issue_orbit(2)
    _issue_orbit(3)
    _issue_orbit(4)
    _issue_orbit(5)
    _drain_step([0, 1, 2, 3, 4, 5])

    # ---- OrbitGreedy step 1 (1 orbit(s)) ----
    _issue_orbit(6)
    _drain_step([6])

    # ---- OrbitGreedy step 2 (1 orbit(s)) ----
    _issue_orbit(7)
    _drain_step([7])

    # ---- OrbitGreedy step 3 (2 orbit(s)) ----
    _issue_orbit(8)
    _issue_orbit(9)
    _drain_step([8, 9])

    # ---- OrbitGreedy step 4 (1 orbit(s)) ----
    _issue_orbit(10)
    _drain_step([10])

    # ---- OrbitGreedy step 5 (1 orbit(s)) ----
    _issue_orbit(11)
    _drain_step([11])

    # ---- OrbitGreedy step 6 (1 orbit(s)) ----
    _issue_orbit(12)
    _drain_step([12])

    # ---- OrbitGreedy step 7 (1 orbit(s)) ----
    _issue_orbit(13)
    _drain_step([13])

    # ---- OrbitGreedy step 8 (1 orbit(s)) ----
    _issue_orbit(14)
    _drain_step([14])

    # ---- OrbitGreedy step 9 (1 orbit(s)) ----
    _issue_orbit(15)
    _drain_step([15])

    # ---- OrbitGreedy step 10 (1 orbit(s)) ----
    _issue_orbit(16)
    _drain_step([16])

    # ---- OrbitGreedy step 11 (1 orbit(s)) ----
    _issue_orbit(17)
    _drain_step([17])

    # ---- OrbitGreedy step 12 (1 orbit(s)) ----
    _issue_orbit(18)
    _drain_step([18])

    # ---- OrbitGreedy step 13 (2 orbit(s)) ----
    _issue_orbit(19)
    _issue_orbit(20)
    _drain_step([19, 20])

    # ---- OrbitGreedy step 14 (1 orbit(s)) ----
    _issue_orbit(21)
    _drain_step([21])

    # ---- OrbitGreedy step 15 (2 orbit(s)) ----
    _issue_orbit(22)
    _issue_orbit(23)
    _drain_step([22, 23])

    # ---- OrbitGreedy step 16 (1 orbit(s)) ----
    _issue_orbit(24)
    _drain_step([24])

    # ---- OrbitGreedy step 17 (2 orbit(s)) ----
    _issue_orbit(25)
    _issue_orbit(26)
    _drain_step([25, 26])

    # ---- OrbitGreedy step 18 (1 orbit(s)) ----
    _issue_orbit(27)
